    qs.append(make_q(c, "LR_BLOOD", "easy", "M is the son of N. N is the daughter of O. How is M related to O?", "Grandson", "Son", "Brother", "Nephew", "A", "Daughter's son is grandson."))
    qs.append(make_q(c, "LR_PUZZLES", "easy", "Statements: Some queries are slow. All slow queries are logged. Conclusion: Some logged items are queries.", "Follows", "Does not follow", "Cannot say", "Invalid", "A", "The slow queries that are logged are queries, so conclusion follows."))
    qs.append(make_q(c, "LR_CODING", "easy", "If 'LTI' is coded as 'MUJ' (+1), what is 'SQL'?", "TRM", "TSM", "URM", "SRM", "A", "S->T, Q->R, L->M => TRM."))
