    qs.append(make_q(c, "VERBAL_RC", "medium", "Passage: 'Continuous deployment automatically deploys all validated code changes directly to production without manual gatekeeping.' What bypasses manual intervention?", "Validated code deployments", "Customer bug reports", "Annual audits", "Hardware procurement", "A", "Validated code deployments occur automatically."))
