    qs.append(make_q(c, "TECH_DSA", "hard", "What is the worst-case time complexity of QuickSort on already sorted data with last element pivot?", "O(N^2)", "O(N log N)", "O(N)", "O(log N)", "A", "Unbalanced partitions yield O(N^2)."))
